import openpyxl, glob, re
try:
    from docx import Document
    HAVE=True
except Exception as e:
    HAVE=False; print('nodocx',e)
# queue ALN-108
wb=openpyxl.load_workbook('Queue/2025-07-14_Active_Queue_Report.xlsx',data_only=True)
ws=wb['Active Queue']
tot=0; rows=[]
for r in ws.iter_rows(min_row=2,values_only=True):
    if r[4]=='ALN-108':
        rows.append(r); cap=r[3]
        m=re.match(r'([\d.]+)\s*(kW|MW)',str(cap)); v=float(m.group(1))*(1 if m.group(2)=='MW' else 0.001); tot+=v
print('ALN108 rows',rows,'tot',tot)
# hosting map
for f in glob.glob('Planning/Hosting*'):
    w=openpyxl.load_workbook(f,data_only=True)
    for s in w.sheetnames:
        x=w[s]
        for rr in x.iter_rows(values_only=True):
            if any(c is not None and 'ALN-108' in str(c) for c in rr): print('MAP',s,rr)
print('---planning study---')
try:
    from docx import Document as D
    d=D('Planning/2024-10-15_ALN-108_Planning_Study.docx')
    txt='\n'.join(p.text for p in d.paragraphs)
    for ln in txt.split('\n'):
        if any(k in ln.lower() for k in ['capacity','mw','limit','thermal','voltage','upgrade','available']): print(ln)
except Exception as e: print('studyerr',e)
EOF

